To safely evaluate mathematical expressions in Python while respecting the order of operations, parentheses, negative numbers, and handling division by zero, we can parse and evaluate the expression using the **Shunting-Yard algorithm** (to convert infix notation to postfix/Reverse Polish Notation) followed by an **RPN evaluator**.

Here is the complete Python function:

```python
def eval_expression(expr: str) -> float:
    # Tokenize the expression, handling negative numbers properly
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        char = expr[i]

        # Skip whitespace
        if char.isspace():
            i += 1
            continue

        # Handle numbers (including decimals and negative numbers)
        if char.isdigit() or char == '.':
            num_str = char
            i += 1
            while i < n and (expr[i].isdigit() or expr[i] == '.'):
                num_str += expr[i]
                i += 1
            tokens.append(float(num_str) if '.' in num_str else int(num_str))

        # Handle operators and parentheses
        elif char in "+-*/()":
            # Check if '-' or '+' is a unary operator (negative/positive sign)
            if char in "+-":
                # It's unary if it's at the start of the expression or follows an operator or '('
                if not tokens or (isinstance(tokens[-1], str) and tokens[-1] in "+-*/("):
                    i += 1
                    # Skip whitespace after sign
                    while i < n and expr[i].isspace():
                        i += 1
                    if i < n and (expr[i].isdigit() or expr[i] == '.'):
                        num_str = expr[i]
                        i += 1
                        while i < n and (expr[i].isdigit() or expr[i] == '.'):
                            num_str += expr[i]
                            i += 1
                        val = float(num_str) if '.' in num_str else int(num_str)
                        tokens.append(-val if char == '-' else val)
                        continue
                    else:
                        raise ValueError(f"Invalid syntax near index {i}")

            tokens.append(char)
            i += 1
        else:
            raise ValueError(f"Invalid character in expression: {char}")

    # Operator precedence
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    # Shunting-yard algorithm to convert to RPN (Postfix)
    output_queue = []
    operator_stack = []

    for token in tokens:
        if isinstance(token, (int, float)):
            output_queue.append(token)
        elif token in precedence:
            while (operator_stack and operator_stack[-1] in precedence and
                   precedence[operator_stack[-1]] >= precedence[token]):
                output_queue.append(operator_stack.pop())
            operator_stack.append(token)
        elif token == '(':
            operator_stack.append(token)
        elif token == ')':
            while operator_stack and operator_stack[-1] != '(':
                output_queue.append(operator_stack.pop())
            if not operator_stack:
                raise ValueError("Mismatched parentheses")
            operator_stack.pop() # Remove '('

    while operator_stack:
        op = operator_stack.pop()
        if op == '(' or op == ')':
            raise ValueError("Mismatched parentheses")
        output_queue.append(op)

    # Evaluate RPN
    eval_stack = []
    for token in output_queue:
        if isinstance(token, (int, float)):
            eval_stack.append(token)
        else:
            if len(eval_stack) < 2:
                raise ValueError("Invalid expression")
            b = eval_stack.pop()
            a = eval_stack.pop()

            if token == '+':
                eval_stack.append(a + b)
            elif token == '-':
                eval_stack.append(a - b)
            elif token == '*':
                eval_stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise ZeroDivisionError("division by zero")
                eval_stack.append(a / b)

    if len(eval_stack) != 1:
        raise ValueError("Invalid expression")

    result = eval_stack[0]
    # Return as int if it's a whole number, otherwise float
    return int(result) if isinstance(result, float) and result.is_integer() else result
```

### Examples of Usage:

```python
print(eval_expression("3 + 4 * (2 - 1)"))        # Output: 7
print(eval_expression("-5 + 2 * (-3 + 5)"))     # Output: -1
print(eval_expression("10 / (5 - 5)"))          # Raises ZeroDivisionError
```

